def papers_search_advanced(query, yearStart=None, yearEnd=None, minCitations=None, openAccessOnly=None, limit=None, fieldsOfStudy=None, publicationTypes=None, sortBy=None, sortOrder=None, **_extra):
    import json, os, datetime, time, math, re, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0495000" if __import__("os").path.isdir("./environment_mix/0495000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    _CROCKFORD = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"

    def _ulid():
        t_ms = int(time.time() * 1000) & ((1 << 48) - 1)
        import os as _os
        r = int.from_bytes(_os.urandom(10), "big")
        v = (t_ms << 80) | r
        out = []
        for _ in range(26):
            out.append(_CROCKFORD[v & 31])
            v >>= 5
        return "".join(reversed(out))

    def _normalize_text(s):
        s = s.lower()
        s = re.sub(r"\s+", " ", s).strip()
        return s

    def _tokenize(s):
        s = _normalize_text(s)
        return re.findall(r"[a-z0-9]+", s)

    def _jaccard(a, b):
        sa, sb = set(a), set(b)
        if not sa and not sb:
            return 0.0
        return len(sa & sb) / float(len(sa | sb))

    def _cosine(u, v):
        if not u or not v:
            return None
        if not isinstance(u, list) or not isinstance(v, list):
            return None
        n = min(len(u), len(v))
        if n == 0:
            return None
        dot = 0.0
        nu = 0.0
        nv = 0.0
        for i in range(n):
            try:
                fu = float(u[i])
                fv = float(v[i])
            except Exception:
                return None
            dot += fu * fv
            nu += fu * fu
            nv += fv * fv
        if nu <= 0.0 or nv <= 0.0:
            return None
        return dot / (math.sqrt(nu) * math.sqrt(nv))

    def _query_embedding(tokens, dim):
        if dim <= 0:
            return None
        vec = [0.0] * dim
        if not tokens:
            return vec
        for tok in tokens:
            h = hashlib.sha256(tok.encode("utf-8")).digest()
            for i in range(0, len(h), 2):
                idx = h[i] % dim
                sign = 1.0 if (h[i + 1] & 1) == 0 else -1.0
                vec[idx] += sign * (1.0 + (h[i + 1] / 255.0))
        norm = math.sqrt(sum(x * x for x in vec))
        if norm > 0:
            vec = [x / norm for x in vec]
        return vec

    def _as_int_year(x, name):
        if x is None:
            return None
        if not isinstance(x, (int, float)) or isinstance(x, bool) or not math.isfinite(float(x)):
            return ("err", _err("VALIDATION_ERROR", f"{name} must be a number"))
        xi = int(x)
        if xi < 1600 or xi > 2100:
            return ("err", _err("VALIDATION_ERROR", f"{name} must be between 1600 and 2100"))
        return xi

    # ---- Validate ----
    if not isinstance(query, str) or not query.strip():
        return _err("VALIDATION_ERROR", "query must be a non-empty string")

    ys = _as_int_year(yearStart, "yearStart")
    if isinstance(ys, tuple) and ys[0] == "err":
        return ys[1]
    ye = _as_int_year(yearEnd, "yearEnd")
    if isinstance(ye, tuple) and ye[0] == "err":
        return ye[1]

    if ys is not None and ye is not None and ys > ye:
        return _err("VALIDATION_ERROR", "yearStart must be <= yearEnd")

    if minCitations is not None:
        if not isinstance(minCitations, (int, float)) or isinstance(minCitations, bool) or not math.isfinite(float(minCitations)):
            return _err("VALIDATION_ERROR", "minCitations must be a number")
        mc = int(minCitations)
        if mc < 0:
            return _err("VALIDATION_ERROR", "minCitations must be >= 0")
    else:
        mc = None

    if openAccessOnly is not None and not isinstance(openAccessOnly, bool):
        return _err("VALIDATION_ERROR", "openAccessOnly must be a boolean")

    if limit is None:
        limit = 10
    if not isinstance(limit, (int, float)) or isinstance(limit, bool) or not math.isfinite(float(limit)):
        return _err("VALIDATION_ERROR", "limit must be a number")
    limit_i = int(limit)
    if limit_i < 0:
        return _err("VALIDATION_ERROR", "limit must be non-negative")
    if limit_i > 100:
        limit_i = 100

    if fieldsOfStudy is not None:
        if not isinstance(fieldsOfStudy, list) or any(not isinstance(x, str) for x in fieldsOfStudy):
            return _err("VALIDATION_ERROR", "fieldsOfStudy must be an array of strings")
        fos = [x.strip() for x in fieldsOfStudy if x.strip()]
    else:
        fos = None

    if publicationTypes is not None:
        if not isinstance(publicationTypes, list) or any(not isinstance(x, str) for x in publicationTypes):
            return _err("VALIDATION_ERROR", "publicationTypes must be an array of strings")
        pts = [x.strip() for x in publicationTypes if x.strip()]
    else:
        pts = None

    if sortBy is None:
        sortBy = "relevance"
    if sortBy not in ("relevance", "citationCount", "year"):
        return _err("VALIDATION_ERROR", "sortBy must be one of: relevance, citationCount, year")

    if sortOrder is None:
        sortOrder = "desc"
    if sortOrder not in ("asc", "desc"):
        return _err("VALIDATION_ERROR", "sortOrder must be one of: asc, desc")

    start = time.time()

    papers = _load("papers.json")
    reqs = _load("search_requests.json")

    q_tokens = _tokenize(query)

    emb_dim = 0
    for p in papers:
        e = p.get("embedding")
        if isinstance(e, list) and len(e) > 0:
            emb_dim = len(e)
            break
    q_emb = _query_embedding(q_tokens, emb_dim) if emb_dim else None

    def _passes_filters(p):
        if p.get("status") != "active":
            return False
        y = p.get("year")
        if ys is not None:
            if not isinstance(y, int) or y < ys:
                return False
        if ye is not None:
            if not isinstance(y, int) or y > ye:
                return False
        if mc is not None:
            cc = p.get("citation_count")
            if not isinstance(cc, int) or cc < mc:
                return False
        if openAccessOnly is True and p.get("is_open_access") is not True:
            return False
        if fos is not None:
            pf = p.get("fields_of_study")
            if not isinstance(pf, list):
                return False
            if len(set(x.lower() for x in pf) & set(x.lower() for x in fos)) == 0:
                return False
        if pts is not None:
            pp = p.get("publication_types")
            if not isinstance(pp, list):
                return False
            if len(set(x.lower() for x in pp) & set(x.lower() for x in pts)) == 0:
                return False
        return True

    filtered = [p for p in papers if _passes_filters(p)]

    # scoring for relevance sorting
    scored = []
    for p in filtered:
        title_norm = p.get("title_normalized") or _normalize_text(p.get("title") or "")
        p_tokens = _tokenize(title_norm)
        text_score = _jaccard(q_tokens, p_tokens)
        emb_score = None
        if q_emb is not None and isinstance(p.get("embedding"), list):
            emb_score = _cosine(q_emb, p.get("embedding"))
        if emb_score is None:
            rel = text_score
        else:
            rel = 0.35 * text_score + 0.65 * emb_score
        scored.append((p, rel))

    reverse = (sortOrder == "desc")

    if sortBy == "relevance":
        scored.sort(
            key=lambda pr: (
                pr[1],
                (pr[0].get("citation_count") if isinstance(pr[0].get("citation_count"), int) else 0),
                (pr[0].get("year") if isinstance(pr[0].get("year"), int) else -1),
                str(pr[0].get("id")),
            ),
            reverse=True if reverse else False,
        )
        ordered = [p for p, _ in scored]
    elif sortBy == "citationCount":
        ordered = sorted(
            filtered,
            key=lambda p: (
                (p.get("citation_count") if isinstance(p.get("citation_count"), int) else 0),
                (p.get("year") if isinstance(p.get("year"), int) else -1),
                str(p.get("id")),
            ),
            reverse=reverse,
        )
    else:  # year
        ordered = sorted(
            filtered,
            key=lambda p: (
                (p.get("year") if isinstance(p.get("year"), int) else -1),
                (p.get("citation_count") if isinstance(p.get("citation_count"), int) else 0),
                str(p.get("id")),
            ),
            reverse=reverse,
        )

    ordered = ordered[:limit_i] if limit_i > 0 else []
    result_ids = [p.get("id") for p in ordered]

    # record request
    now = _now_iso()
    req_row = {
        "id": _ulid(),
        "tool_name": "papers-search-advanced",
        "query": query,
        "title": None,
        "paper_id_input": None,
        "author_id_input": None,
        "paper_ids_input": None,
        "year_start": ys,
        "year_end": ye,
        "min_citations": mc,
        "open_access_only": openAccessOnly if openAccessOnly is not None else None,
        "fields_of_study": fos,
        "publication_types": pts,
        "sort_by": sortBy,
        "sort_order": sortOrder,
        "limit": limit_i,
        "offset": None,
        "depth": None,
        "citations_limit": None,
        "references_limit": None,
        "resolved_root_paper_id": None,
        "resolved_author_id": None,
        "result_paper_ids": result_ids,
        "result_author_ids": None,
        "status": "succeeded",
        "error_message": None,
        "created_at": now,
        "updated_at": now,
    }
    reqs.append(req_row)
    _save("search_requests.json", reqs)

    latency_ms = int((time.time() - start) * 1000)

    # rate limit (same as other tools)
    window_s = 60
    max_per_window = 120
    try:
        now_dt = datetime.datetime.utcnow()
        cutoff = now_dt - datetime.timedelta(seconds=window_s)

        def _parse(ts):
            if not isinstance(ts, str):
                return None
            try:
                if ts.endswith("Z"):
                    ts = ts[:-1]
                return datetime.datetime.fromisoformat(ts)
            except Exception:
                return None

        recent = 0
        for r in reqs:
            dt = _parse(r.get("created_at"))
            if dt is not None and dt >= cutoff:
                recent += 1
        if recent > max_per_window:
            req_row["status"] = "failed"
            req_row["error_message"] = "Rate limit exceeded"
            req_row["updated_at"] = _now_iso()
            _save("search_requests.json", reqs)
            return _err("QUOTA_EXCEEDED", "request rate exceeds allowed limits", retry_after_seconds=window_s)
    except Exception:
        return _err("VALIDATION_ERROR", "internal rate limit state invalid")

    return {
        "data": {
            "papers": ordered,
            "result_paper_ids": result_ids,
        },
        "meta": {"limit": limit_i, "sort_by": sortBy, "sort_order": sortOrder, "latency_ms": latency_ms},
    }

def papers_match(title, yearStart=None, yearEnd=None, minCitations=None, openAccessOnly=None, **_extra):
    import json, os, datetime, time, math, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0495000" if __import__("os").path.isdir("./environment_mix/0495000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    _CROCKFORD = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"

    def _ulid():
        t_ms = int(time.time() * 1000) & ((1 << 48) - 1)
        import os as _os
        r = int.from_bytes(_os.urandom(10), "big")
        v = (t_ms << 80) | r
        out = []
        for _ in range(26):
            out.append(_CROCKFORD[v & 31])
            v >>= 5
        return "".join(reversed(out))

    def _normalize_text(s):
        s = s.lower()
        s = re.sub(r"\s+", " ", s).strip()
        return s

    def _trigrams(s):
        s = re.sub(r"\s+", " ", _normalize_text(s))
        s = f"  {s}  "
        return [s[i : i + 3] for i in range(max(0, len(s) - 2))]

    def _cosine_counts(a, b):
        # cosine similarity over trigram counts
        from collections import Counter
        ca = Counter(a)
        cb = Counter(b)
        if not ca or not cb:
            return 0.0
        dot = 0
        na = 0
        nb = 0
        for k, va in ca.items():
            na += va * va
            vb = cb.get(k)
            if vb:
                dot += va * vb
        for vb in cb.values():
            nb += vb * vb
        if na == 0 or nb == 0:
            return 0.0
        return float(dot) / (math.sqrt(na) * math.sqrt(nb))

    def _as_int_year(x, name):
        if x is None:
            return None
        if not isinstance(x, (int, float)) or isinstance(x, bool) or not math.isfinite(float(x)):
            return ("err", _err("VALIDATION_ERROR", f"{name} must be a number"))
        xi = int(x)
        if xi < 1600 or xi > 2100:
            return ("err", _err("VALIDATION_ERROR", f"{name} must be between 1600 and 2100"))
        return xi

    if not isinstance(title, str) or not title.strip():
        return _err("VALIDATION_ERROR", "title must be a non-empty string")

    ys = _as_int_year(yearStart, "yearStart")
    if isinstance(ys, tuple) and ys[0] == "err":
        return ys[1]
    ye = _as_int_year(yearEnd, "yearEnd")
    if isinstance(ye, tuple) and ye[0] == "err":
        return ye[1]
    if ys is not None and ye is not None and ys > ye:
        return _err("VALIDATION_ERROR", "yearStart must be <= yearEnd")

    if minCitations is not None:
        if not isinstance(minCitations, (int, float)) or isinstance(minCitations, bool) or not math.isfinite(float(minCitations)):
            return _err("VALIDATION_ERROR", "minCitations must be a number")
        mc = int(minCitations)
        if mc < 0:
            return _err("VALIDATION_ERROR", "minCitations must be >= 0")
    else:
        mc = None

    if openAccessOnly is not None and not isinstance(openAccessOnly, bool):
        return _err("VALIDATION_ERROR", "openAccessOnly must be a boolean")

    start = time.time()
    papers = _load("papers.json")
    reqs = _load("search_requests.json")

    title_norm = _normalize_text(title)
    q_tri = _trigrams(title_norm)

    best = None  # (score, citation_count, year, id, paper)
    for p in papers:
        if p.get("status") != "active":
            continue
        y = p.get("year")
        if ys is not None:
            if not isinstance(y, int) or y < ys:
                continue
        if ye is not None:
            if not isinstance(y, int) or y > ye:
                continue
        if mc is not None:
            cc = p.get("citation_count")
            if not isinstance(cc, int) or cc < mc:
                continue
        if openAccessOnly is True and p.get("is_open_access") is not True:
            continue

        pn = p.get("title_normalized") or _normalize_text(p.get("title") or "")
        score = _cosine_counts(q_tri, _trigrams(pn))

        cc = p.get("citation_count") if isinstance(p.get("citation_count"), int) else 0
        yr = p.get("year") if isinstance(p.get("year"), int) else -1
        pid = str(p.get("id"))

        cand = (score, cc, yr, pid, p)
        if best is None:
            best = cand
        else:
            # ties break by higher citation_count then newer year
            if cand[0] > best[0]:
                best = cand
            elif cand[0] == best[0]:
                if cand[1] > best[1]:
                    best = cand
                elif cand[1] == best[1]:
                    if cand[2] > best[2]:
                        best = cand
                    elif cand[2] == best[2] and cand[3] < best[3]:
                        best = cand

    matched_paper = best[4] if best is not None else None
    result_ids = [matched_paper.get("id")] if matched_paper else []

    # record request
    now = _now_iso()
    req_row = {
        "id": _ulid(),
        "tool_name": "papers-match",
        "query": None,
        "title": title,
        "paper_id_input": None,
        "author_id_input": None,
        "paper_ids_input": None,
        "year_start": ys,
        "year_end": ye,
        "min_citations": mc,
        "open_access_only": openAccessOnly if openAccessOnly is not None else None,
        "fields_of_study": None,
        "publication_types": None,
        "sort_by": None,
        "sort_order": None,
        "limit": None,
        "offset": None,
        "depth": None,
        "citations_limit": None,
        "references_limit": None,
        "resolved_root_paper_id": None,
        "resolved_author_id": None,
        "result_paper_ids": result_ids,
        "result_author_ids": None,
        "status": "succeeded",
        "error_message": None,
        "created_at": now,
        "updated_at": now,
    }
    reqs.append(req_row)
    _save("search_requests.json", reqs)

    latency_ms = int((time.time() - start) * 1000)

    # rate limit
    window_s = 60
    max_per_window = 120
    try:
        now_dt = datetime.datetime.utcnow()
        cutoff = now_dt - datetime.timedelta(seconds=window_s)

        def _parse(ts):
            if not isinstance(ts, str):
                return None
            try:
                if ts.endswith("Z"):
                    ts = ts[:-1]
                return datetime.datetime.fromisoformat(ts)
            except Exception:
                return None

        recent = 0
        for r in reqs:
            dt = _parse(r.get("created_at"))
            if dt is not None and dt >= cutoff:
                recent += 1
        if recent > max_per_window:
            req_row["status"] = "failed"
            req_row["error_message"] = "Rate limit exceeded"
            req_row["updated_at"] = _now_iso()
            _save("search_requests.json", reqs)
            return _err("QUOTA_EXCEEDED", "request rate exceeds allowed limits", retry_after_seconds=window_s)
    except Exception:
        return _err("VALIDATION_ERROR", "internal rate limit state invalid")

    return {
        "data": {
            "paper": matched_paper,
            "matched": True if matched_paper else False,
            "score": (best[0] if best is not None else None),
        },
        "meta": {"latency_ms": latency_ms},
    }

def papers_get(paperId, **_extra):
    import json, os, datetime, time, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0495000" if __import__("os").path.isdir("./environment_mix/0495000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    _CROCKFORD = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"

    def _ulid():
        t_ms = int(time.time() * 1000) & ((1 << 48) - 1)
        import os as _os
        r = int.from_bytes(_os.urandom(10), "big")
        v = (t_ms << 80) | r
        out = []
        for _ in range(26):
            out.append(_CROCKFORD[v & 31])
            v >>= 5
        return "".join(reversed(out))

    def _normalize_doi(s):
        s = s.strip()
        s = re.sub(r"^https?://(dx\.)?doi\.org/", "", s, flags=re.I)
        return s.strip().lower()

    start = time.time()

    if not isinstance(paperId, str) or not paperId.strip():
        return _err("VALIDATION_ERROR", "paperId must be a non-empty string")

    papers = _load("papers.json")
    reqs = _load("search_requests.json")

    pid_in = paperId.strip()
    doi_norm = _normalize_doi(pid_in)

    by_id = {p.get("id"): p for p in papers if isinstance(p.get("id"), str)}
    by_s2 = {}
    by_doi = {}
    by_arxiv = {}
    by_pubmed = {}
    for p in papers:
        s2 = p.get("s2_paper_id")
        if isinstance(s2, str) and s2:
            by_s2[s2] = p
        d = p.get("doi")
        if isinstance(d, str) and d:
            by_doi[d.lower()] = p
        a = p.get("arxiv_id")
        if isinstance(a, str) and a:
            by_arxiv[a] = p
        pm = p.get("pubmed_id")
        if isinstance(pm, str) and pm:
            by_pubmed[pm] = p

    resolved = None
    # resolve order: internal id, s2_paper_id, doi (normalized), arxiv_id, pubmed_id
    if pid_in in by_id:
        resolved = by_id[pid_in]
    elif pid_in in by_s2:
        resolved = by_s2[pid_in]
    elif doi_norm and doi_norm in by_doi:
        resolved = by_doi[doi_norm]
    elif pid_in in by_arxiv:
        resolved = by_arxiv[pid_in]
    elif pid_in in by_pubmed:
        resolved = by_pubmed[pid_in]

    # If merged, return merged-into record
    if resolved and resolved.get("status") == "merged":
        target_id = resolved.get("merged_into_paper_id")
        if isinstance(target_id, str) and target_id in by_id:
            resolved = by_id[target_id]
        else:
            # store integrity issue
            resolved = None

    # record request regardless of outcome
    now = _now_iso()
    req_row = {
        "id": _ulid(),
        "tool_name": "papers-get",
        "query": None,
        "title": None,
        "paper_id_input": paperId,
        "author_id_input": None,
        "paper_ids_input": None,
        "year_start": None,
        "year_end": None,
        "min_citations": None,
        "open_access_only": None,
        "fields_of_study": None,
        "publication_types": None,
        "sort_by": None,
        "sort_order": None,
        "limit": None,
        "offset": None,
        "depth": None,
        "citations_limit": None,
        "references_limit": None,
        "resolved_root_paper_id": (resolved.get("id") if resolved else None),
        "resolved_author_id": None,
        "result_paper_ids": ([resolved.get("id")] if resolved else []),
        "result_author_ids": None,
        "status": "succeeded" if resolved else "failed",
        "error_message": None if resolved else "Not found",
        "created_at": now,
        "updated_at": now,
    }
    reqs.append(req_row)
    _save("search_requests.json", reqs)

    latency_ms = int((time.time() - start) * 1000)

    # rate limit
    window_s = 60
    max_per_window = 120
    try:
        now_dt = datetime.datetime.utcnow()
        cutoff = now_dt - datetime.timedelta(seconds=window_s)

        def _parse(ts):
            if not isinstance(ts, str):
                return None
            try:
                if ts.endswith("Z"):
                    ts = ts[:-1]
                return datetime.datetime.fromisoformat(ts)
            except Exception:
                return None

        recent = 0
        for r in reqs:
            dt = _parse(r.get("created_at"))
            if dt is not None and dt >= cutoff:
                recent += 1
        if recent > max_per_window:
            req_row["status"] = "failed"
            req_row["error_message"] = "Rate limit exceeded"
            req_row["updated_at"] = _now_iso()
            _save("search_requests.json", reqs)
            return _err("QUOTA_EXCEEDED", "request rate exceeds allowed limits", retry_after_seconds=window_s)
    except Exception:
        return _err("VALIDATION_ERROR", "internal rate limit state invalid")

    if not resolved:
        return _err("NOT_FOUND", "No paper found for the given identifier")

    return {"data": {"paper": resolved}, "meta": {"latency_ms": latency_ms}}

def papers_references(paperId, limit=None, offset=None, **_extra):
    import json, os, datetime, time, math, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0495000" if __import__("os").path.isdir("./environment_mix/0495000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    _t0 = time.time()

    # ---------- helpers ----------
    def _append_request(req_row):
        reqs = _load("search_requests.json")
        reqs.append(req_row)
        _save("search_requests.json", reqs)

    def _ulid_like():
        # Not a real ULID, but stable unique id with time prefix; sufficient for local store.
        ts = int(time.time() * 1000)
        r = random.getrandbits(40)
        return f"01H{ts:010d}{r:010x}".upper()

    def _norm_doi(x):
        if not isinstance(x, str):
            return None
        s = x.strip()
        if not s:
            return None
        lo = s.lower()
        if lo.startswith("doi:"):
            lo = lo[4:].strip()
        if lo.startswith("https://doi.org/"):
            lo = lo[len("https://doi.org/") :].strip()
        if lo.startswith("http://doi.org/"):
            lo = lo[len("http://doi.org/") :].strip()
        return lo

    def _is_intlike(n):
        if isinstance(n, bool):
            return False
        if isinstance(n, int):
            return True
        if isinstance(n, float) and math.isfinite(n) and float(n).is_integer():
            return True
        return False

    def _resolve_paper(papers, pid_input):
        # Order: internal id, s2_paper_id, doi(normalized), arxiv_id, pubmed_id
        if not isinstance(pid_input, str) or not pid_input.strip():
            return None
        raw = pid_input.strip()

        by_id = {p.get("id"): p for p in papers if isinstance(p, dict)}
        p = by_id.get(raw)

        if p is None:
            for q in papers:
                if isinstance(q, dict) and q.get("s2_paper_id") == raw:
                    p = q
                    break

        if p is None:
            doi = _norm_doi(raw)
            if doi:
                for q in papers:
                    if isinstance(q, dict) and q.get("doi") == doi:
                        p = q
                        break

        if p is None:
            for q in papers:
                if isinstance(q, dict) and q.get("arxiv_id") == raw:
                    p = q
                    break

        if p is None:
            for q in papers:
                if isinstance(q, dict) and q.get("pubmed_id") == raw:
                    p = q
                    break

        if p is None:
            return None

        # If merged, return surviving paper record
        if p.get("status") == "merged":
            target_id = p.get("merged_into_paper_id")
            if target_id and target_id in by_id:
                return by_id[target_id]
        return p

    # ---------- validate inputs ----------
    if not isinstance(paperId, str) or not paperId.strip():
        return _err("VALIDATION_ERROR", "paperId must be a non-empty string", field="paperId")

    if limit is None:
        limit = 10
    if offset is None:
        offset = 0

    # Tool description says "non-negative number" for limit; business rules: default 10 and clamp max to 100
    if not _is_intlike(limit):
        return _err("VALIDATION_ERROR", "limit must be a non-negative number", field="limit")
    if not _is_intlike(offset):
        return _err("VALIDATION_ERROR", "offset must be a non-negative number", field="offset")

    limit = int(limit)
    offset = int(offset)

    if offset < 0:
        return _err("VALIDATION_ERROR", "offset must be >= 0", field="offset")
    if limit < 0:
        return _err("VALIDATION_ERROR", "limit must be >= 0", field="limit")

    # Clamp per business rule (and schema caps at 100 when provided)
    if limit == 0:
        clamped_limit = 0
    else:
        clamped_limit = max(1, min(100, limit))
    limit = clamped_limit

    # ---------- authorize & rate limit ----------
    # No explicit credentials in tool signature; treat as authenticated if service is usable.
    # Enforce a simple per-minute rate limit using search_requests as the observable log.
    # If search_requests doesn't exist yet, _load returns [] and we proceed.
    now = datetime.datetime.utcnow()
    reqs_existing = _load("search_requests.json")
    # keep only parseable timestamps for rate checks
    window_start = now - datetime.timedelta(seconds=60)
    count_60s = 0
    for r in reqs_existing:
        if not isinstance(r, dict):
            continue
        ts = r.get("created_at") or r.get("updated_at")
        if not isinstance(ts, str):
            continue
        try:
            # accept "Z" suffix
            ts2 = ts.replace("Z", "+00:00")
            dt = datetime.datetime.fromisoformat(ts2)
            if dt.tzinfo is not None:
                dt = dt.astimezone(datetime.timezone.utc).replace(tzinfo=None)
            if dt >= window_start:
                count_60s += 1
        except Exception:
            continue
    # Global limit: 120 requests/minute
    if count_60s >= 120:
        # Log refused call as failed request
        req_row = {
            "id": _ulid_like(),
            "tool_name": "papers-references",
            "query": None,
            "title": None,
            "paper_id_input": paperId,
            "author_id_input": None,
            "paper_ids_input": None,
            "year_start": None,
            "year_end": None,
            "min_citations": None,
            "open_access_only": None,
            "fields_of_study": None,
            "publication_types": None,
            "sort_by": None,
            "sort_order": None,
            "limit": limit,
            "offset": offset,
            "depth": None,
            "citations_limit": None,
            "references_limit": None,
            "resolved_root_paper_id": None,
            "resolved_author_id": None,
            "result_paper_ids": None,
            "result_author_ids": None,
            "status": "failed",
            "error_message": "Rate limit exceeded",
            "created_at": _now_iso(),
            "updated_at": _now_iso(),
        }
        _append_request(req_row)
        return _err("RATE_LIMIT", "Rate limit exceeded")

    # ---------- create request row (queued->running->succeeded/failed) ----------
    req_id = _ulid_like()
    created_at = _now_iso()
    req_row = {
        "id": req_id,
        "tool_name": "papers-references",
        "query": None,
        "title": None,
        "paper_id_input": paperId,
        "author_id_input": None,
        "paper_ids_input": None,
        "year_start": None,
        "year_end": None,
        "min_citations": None,
        "open_access_only": None,
        "fields_of_study": None,
        "publication_types": None,
        "sort_by": None,
        "sort_order": None,
        "limit": limit,
        "offset": offset,
        "depth": None,
        "citations_limit": None,
        "references_limit": None,
        "resolved_root_paper_id": None,
        "resolved_author_id": None,
        "result_paper_ids": None,
        "result_author_ids": None,
        "status": "queued",
        "error_message": None,
        "created_at": created_at,
        "updated_at": created_at,
    }
    _append_request(req_row)

    # Transition queued -> running
    reqs = _load("search_requests.json")
    for r in reqs:
        if isinstance(r, dict) and r.get("id") == req_id:
            r["status"] = "running"
            r["updated_at"] = _now_iso()
            break
    _save("search_requests.json", reqs)

    papers = _load("papers.json")
    citations = _load("paper_citations.json")

    resolved = _resolve_paper(papers, paperId)
    if resolved is None:
        # running -> failed
        reqs = _load("search_requests.json")
        for r in reqs:
            if isinstance(r, dict) and r.get("id") == req_id:
                r["status"] = "failed"
                r["error_message"] = "Source paper not found"
                r["updated_at"] = _now_iso()
                break
        _save("search_requests.json", reqs)
        return _err("NOT_FOUND", "Source paper not found", paperId=paperId)

    root_id = resolved.get("id")
    by_id = {p.get("id"): p for p in papers if isinstance(p, dict)}
    # Join: citing_paper_id = resolved target, status='active' => references (papers cited by target)
    ref_ids = []
    seen = set()
    for e in citations:
        if not isinstance(e, dict):
            continue
        if e.get("status") != "active":
            continue
        if e.get("citing_paper_id") != root_id:
            continue
        cid = e.get("cited_paper_id")
        if not isinstance(cid, str) or not cid:
            continue
        if cid in seen:
            continue
        # FK integrity
        if cid not in by_id:
            continue
        # omit tombstoned/merged records; if merged, resolve to survivor
        p = by_id[cid]
        if p.get("status") == "tombstoned":
            continue
        if p.get("status") == "merged":
            tgt = p.get("merged_into_paper_id")
            if isinstance(tgt, str) and tgt in by_id and by_id[tgt].get("status") == "active":
                cid = tgt
            else:
                continue
        seen.add(cid)
        ref_ids.append(cid)

    def _sort_key(pid):
        p = by_id.get(pid) or {}
        year = p.get("year")
        year_key = year if isinstance(year, int) else -1
        cc = p.get("citation_count")
        cc_key = cc if isinstance(cc, int) else 0
        return (-year_key, -cc_key, str(pid))

    ref_ids_sorted = sorted(ref_ids, key=_sort_key)

    total = len(ref_ids_sorted)
    slice_ids = ref_ids_sorted[offset : offset + limit] if limit != 0 else []
    rows = [by_id[i] for i in slice_ids if i in by_id]

    # Persist results into request row and mark succeeded
    reqs = _load("search_requests.json")
    for r in reqs:
        if isinstance(r, dict) and r.get("id") == req_id:
            r["resolved_root_paper_id"] = root_id
            r["result_paper_ids"] = slice_ids
            r["status"] = "succeeded"
            r["error_message"] = None
            r["updated_at"] = _now_iso()
            break
    _save("search_requests.json", reqs)

    has_more = (offset + (0 if limit == 0 else limit)) < total
    next_cursor = (offset + limit) if has_more and limit != 0 else None

    return {
        "request": {"id": req_id, "status": "succeeded"},
        "data": rows,
        "meta": {
            "resolved_paper_id": root_id,
            "total": total,
            "limit": limit,
            "offset": offset,
            "has_more": has_more,
            "next_cursor": next_cursor,
            "latency_ms": int((time.time() - _t0) * 1000),
        },
    }

def authors_search(query, limit=None, offset=None, **_extra):
    import json, os, datetime, time, math, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0495000" if __import__("os").path.isdir("./environment_mix/0495000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _gen_ulid():
        import os, time
        ms = int(time.time() * 1000)
        ts = ms.to_bytes(6, "big", signed=False)
        rnd = os.urandom(10)
        b = ts + rnd
        enc = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        n = int.from_bytes(b, "big", signed=False)
        out = []
        for _ in range(26):
            n, r = divmod(n, 32)
            out.append(enc[r])
        return "".join(reversed(out))

    def _parse_nonneg_int(val, name, default):
        if val is None:
            val = default
        if isinstance(val, bool):
            return None, _err("VALIDATION_ERROR", f"{name} must be a number")
        if isinstance(val, (int, float)):
            if isinstance(val, float):
                if not math.isfinite(val) or abs(val - int(val)) > 0:
                    return None, _err("VALIDATION_ERROR", f"{name} must be an integer")
                val = int(val)
            if val < 0:
                return None, _err("VALIDATION_ERROR", f"{name} must be >= 0")
            return int(val), None
        return None, _err("VALIDATION_ERROR", f"{name} must be a number")

    def _rate_and_log(tool_name, status, latency_ms, **req_fields):
        logs = _load("usage_logs.json")
        if not isinstance(logs, list):
            logs = []
        cutoff = time.time() - 60.0
        recent = 0
        for r in logs:
            ts = r.get("ts_epoch")
            if isinstance(ts, (int, float)) and ts >= cutoff:
                if r.get("tool_name") == tool_name:
                    recent += 1
        if status == "precheck":
            if recent >= 120:
                row = {
                    "id": _gen_ulid(),
                    "tool_name": tool_name,
                    "status": "RATE_LIMIT",
                    "latency_ms": 0,
                    "ts": now,
                    "ts_epoch": time.time(),
                }
                row.update(req_fields)
                logs.append(row)
                _save("usage_logs.json", logs)
                return _err("RATE_LIMIT", "Rate limit exceeded")
            return None
        row = {
            "id": _gen_ulid(),
            "tool_name": tool_name,
            "status": status,
            "latency_ms": int(latency_ms),
            "ts": now,
            "ts_epoch": time.time(),
        }
        row.update(req_fields)
        logs.append(row)
        _save("usage_logs.json", logs)
        return None

    rl = _rate_and_log("authors-search", "precheck", 0, query=query)
    if rl:
        return rl

    if not isinstance(query, str):
        latency = (time.time() - t0) * 1000
        _rate_and_log("authors-search", "VALIDATION_ERROR", latency, query=query)
        return _err("VALIDATION_ERROR", "query must be a string")
    q = " ".join(query.strip().split())
    if not q:
        latency = (time.time() - t0) * 1000
        _rate_and_log("authors-search", "VALIDATION_ERROR", latency, query=query)
        return _err("VALIDATION_ERROR", "query must be non-empty")

    offset_i, e = _parse_nonneg_int(offset, "offset", 0)
    if e:
        latency = (time.time() - t0) * 1000
        _rate_and_log("authors-search", "VALIDATION_ERROR", latency, query=q, offset=offset)
        return e
    limit_i, e = _parse_nonneg_int(limit, "limit", 10)
    if e:
        latency = (time.time() - t0) * 1000
        _rate_and_log("authors-search", "VALIDATION_ERROR", latency, query=q, limit=limit)
        return e

    if limit_i < 1:
        limit_i = 0
    if limit_i > 100:
        limit_i = 100

    authors = _load("authors.json")
    if not isinstance(authors, list):
        authors = []

    qn = q.lower()
    q_terms = [t for t in re.split(r"\s+", qn) if t]

    def _score(a):
        # Higher is better
        name_n = a.get("name_normalized") if isinstance(a, dict) else ""
        if not isinstance(name_n, str):
            name_n = ""
        affs = a.get("affiliations") if isinstance(a, dict) else []
        if not isinstance(affs, list):
            affs = []
        aff_text = " ".join([x for x in affs if isinstance(x, str)]).lower()

        score = 0
        if qn == name_n:
            score += 1000
        if qn and qn in name_n:
            score += 200 + int(100 * (len(qn) / max(1, len(name_n))))
        # term coverage
        covered = 0
        for t in q_terms:
            if t in name_n or t in aff_text:
                covered += 1
        score += covered * 50

        if qn and qn in aff_text:
            score += 40

        pc = a.get("paper_count")
        if not isinstance(pc, int):
            pc = 0
        cc = a.get("citation_count")
        if not isinstance(cc, int):
            cc = 0
        score += min(200, int(math.log10(cc + 1) * 50))
        score += min(100, int(math.log10(pc + 1) * 30))
        return score

    matches = []
    for a in authors:
        if not isinstance(a, dict):
            continue
        if a.get("status") not in (None, "active", "merged", "tombstoned"):
            continue
        name_n = a.get("name_normalized")
        affs = a.get("affiliations")
        if not isinstance(name_n, str):
            name_n = ""
        if not isinstance(affs, list):
            affs = []
        hay = name_n + " " + " ".join([x for x in affs if isinstance(x, str)]).lower()
        if all(t in hay for t in q_terms):
            matches.append(a)

    # Stable ordering: score desc, citation_count desc, paper_count desc, id asc
    def _key(a):
        aid = a.get("id") if isinstance(a.get("id"), str) else ""
        cc = a.get("citation_count")
        if not isinstance(cc, int):
            cc = 0
        pc = a.get("paper_count")
        if not isinstance(pc, int):
            pc = 0
        return (-_score(a), -cc, -pc, aid)

    matches.sort(key=_key)

    total = len(matches)
    page = matches[offset_i: offset_i + limit_i] if offset_i <= total else []
    result_author_ids = [a.get("id") for a in page if isinstance(a.get("id"), str)]

    sr = _load("search_requests.json")
    if not isinstance(sr, list):
        sr = []
    sr_row = {
        "id": _gen_ulid(),
        "tool_name": "authors-search",
        "query": q,
        "title": None,
        "paper_id_input": None,
        "author_id_input": None,
        "paper_ids_input": None,
        "year_start": None,
        "year_end": None,
        "min_citations": None,
        "open_access_only": None,
        "fields_of_study": None,
        "publication_types": None,
        "sort_by": None,
        "sort_order": None,
        "limit": limit_i,
        "offset": offset_i,
        "depth": None,
        "citations_limit": None,
        "references_limit": None,
        "resolved_root_paper_id": None,
        "resolved_author_id": None,
        "result_paper_ids": None,
        "result_author_ids": result_author_ids,
        "status": "succeeded",
        "error_message": None,
        "created_at": now,
        "updated_at": now,
    }
    sr.append(sr_row)
    _save("search_requests.json", sr)

    latency = (time.time() - t0) * 1000
    _rate_and_log("authors-search", "OK", latency, query=q, offset=offset_i, limit=limit_i)

    return {
        "data": page,
        "meta": {
            "total": total,
            "offset": offset_i,
            "limit": limit_i,
            "has_more": (offset_i + len(page)) < total,
            "next_offset": (offset_i + len(page)) if (offset_i + len(page)) < total else None,
            "request_id": sr_row["id"],
        },
    }

def authors_papers(authorId=None, limit=None, offset=None, **_extra):
    import json, os, datetime, time, math

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0495000" if __import__("os").path.isdir("./environment_mix/0495000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    def _gen_id(prefix):
        import os as _os
        ms = int(time.time() * 1000)
        b = ms.to_bytes(6, "big", signed=False) + _os.urandom(10)
        enc = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        n = int.from_bytes(b, "big", signed=False)
        out = []
        for _ in range(26):
            n, r = divmod(n, 32)
            out.append(enc[r])
        return f"{prefix}_{''.join(reversed(out))}"

    def _append_usage(status_s, latency_ms, **req_fields):
        logs = _load("usage_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": _gen_id("ulog"),
            "endpoint": "authors-papers",
            "tool_name": "authors-papers",
            "status": status_s,
            "latency_ms": int(latency_ms),
            "timestamp": now,
            "ts_epoch": time.time(),
        }
        if req_fields:
            row.update(req_fields)
        logs.append(row)
        _save("usage_logs.json", logs)

    def _rate_limit_check():
        logs = _load("usage_logs.json")
        if not isinstance(logs, list):
            return None
        cutoff = time.time() - 60.0
        recent = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("endpoint") != "authors-papers" and r.get("tool_name") != "authors-papers":
                continue
            ts = r.get("ts_epoch")
            if isinstance(ts, (int, float)) and ts >= cutoff:
                recent += 1
        if recent >= 120:
            return _err("RATE_LIMIT", "Rate limit exceeded")
        return None

    def _parse_int(val, name, default):
        if val is None:
            val = default
        if isinstance(val, bool):
            return None, _err("VALIDATION_ERROR", f"{name} must be a number", field=name)
        if isinstance(val, (int, float)):
            if isinstance(val, float):
                if not math.isfinite(val) or abs(val - int(val)) > 0:
                    return None, _err("VALIDATION_ERROR", f"{name} must be an integer", field=name)
                val = int(val)
            return int(val), None
        return None, _err("VALIDATION_ERROR", f"{name} must be a number", field=name)

    def _stable_paper_sort_key(p):
        y = p.get("year")
        yv = y if isinstance(y, int) else -1
        cc = p.get("citation_count")
        ccv = cc if isinstance(cc, int) else 0
        return (-yv, -ccv, str(p.get("id") or ""))

    try:
        rl = _rate_limit_check()
        if rl:
            _append_usage("RATE_LIMIT", (time.time() - t0) * 1000, author_id_input=authorId, limit=limit, offset=offset)
            return rl

        if not isinstance(authorId, str) or not authorId.strip():
            _append_usage("VALIDATION_ERROR", (time.time() - t0) * 1000, author_id_input=authorId, limit=limit, offset=offset)
            return _err("VALIDATION_ERROR", "authorId must be a non-empty string", field="authorId")
        authorId = authorId.strip()

        limit_i, e = _parse_int(limit, "limit", 10)
        if e:
            _append_usage("VALIDATION_ERROR", (time.time() - t0) * 1000, author_id_input=authorId, limit=limit, offset=offset)
            return e
        offset_i, e = _parse_int(offset, "offset", 0)
        if e:
            _append_usage("VALIDATION_ERROR", (time.time() - t0) * 1000, author_id_input=authorId, limit=limit, offset=offset)
            return e

        if offset_i < 0:
            _append_usage("VALIDATION_ERROR", (time.time() - t0) * 1000, author_id_input=authorId, limit=limit_i, offset=offset_i)
            return _err("VALIDATION_ERROR", "offset must be >= 0", field="offset")

        # Enforce service defaults/clamps (business rule)
        if limit_i <= 0:
            _append_usage("VALIDATION_ERROR", (time.time() - t0) * 1000, author_id_input=authorId, limit=limit_i, offset=offset_i)
            return _err("VALIDATION_ERROR", "limit must be >= 1", field="limit")
        if limit_i > 100:
            limit_i = 100

        authors = _load("authors.json")
        if isinstance(authors, dict) and "rows" in authors and isinstance(authors["rows"], list):
            authors = authors["rows"]
        if not isinstance(authors, list):
            authors = []

        # Find author; if merged, resolve to surviving author id
        author_row = None
        for a in authors:
            if isinstance(a, dict) and a.get("id") == authorId:
                author_row = a
                break
        if author_row is None:
            _append_usage("NOT_FOUND", (time.time() - t0) * 1000, author_id_input=authorId, limit=limit_i, offset=offset_i)
            return _err("NOT_FOUND", "Author not found", field="authorId")

        resolved_author_id = author_row.get("id")
        if author_row.get("status") == "merged":
            mid = author_row.get("merged_into_author_id")
            if not isinstance(mid, str) or not mid.strip():
                _append_usage("CONFLICT", (time.time() - t0) * 1000, author_id_input=authorId, resolved_author_id=resolved_author_id, limit=limit_i, offset=offset_i)
                return _err("CONFLICT", "Author record is merged but missing merged_into_author_id", field="authorId")
            resolved_author_id = mid.strip()

            # ensure merged-into exists
            exists = False
            for a in authors:
                if isinstance(a, dict) and a.get("id") == resolved_author_id:
                    exists = True
                    break
            if not exists:
                _append_usage("NOT_FOUND", (time.time() - t0) * 1000, author_id_input=authorId, resolved_author_id=resolved_author_id, limit=limit_i, offset=offset_i)
                return _err("NOT_FOUND", "Merged author target not found", field="authorId")

        if author_row.get("status") == "tombstoned":
            _append_usage("NOT_FOUND", (time.time() - t0) * 1000, author_id_input=authorId, resolved_author_id=resolved_author_id, limit=limit_i, offset=offset_i)
            return _err("NOT_FOUND", "Author not found", field="authorId")

        paper_authors = _load("paper_authors.json")
        if isinstance(paper_authors, dict) and "rows" in paper_authors and isinstance(paper_authors["rows"], list):
            paper_authors = paper_authors["rows"]
        if not isinstance(paper_authors, list):
            paper_authors = []

        papers = _load("papers.json")
        if isinstance(papers, dict) and "rows" in papers and isinstance(papers["rows"], list):
            papers = papers["rows"]
        if not isinstance(papers, list):
            papers = []

        paper_by_id = {p.get("id"): p for p in papers if isinstance(p, dict) and isinstance(p.get("id"), str)}

        # FK integrity: only include join rows referencing existing papers
        author_paper_ids = []
        seen = set()
        for pa in paper_authors:
            if not isinstance(pa, dict):
                continue
            if pa.get("author_id") != resolved_author_id:
                continue
            pid = pa.get("paper_id")
            if not isinstance(pid, str) or pid not in paper_by_id:
                continue
            if pid in seen:
                continue
            seen.add(pid)
            author_paper_ids.append(pid)

        # Resolve merged papers to their surviving record (per papers-get rule, reused here)
        def _resolve_paper_id(pid):
            p = paper_by_id.get(pid)
            if not isinstance(p, dict):
                return None
            if p.get("status") == "merged":
                mid = p.get("merged_into_paper_id")
                if isinstance(mid, str) and mid in paper_by_id:
                    return mid
            if p.get("status") == "tombstoned":
                return None
            return pid

        resolved_ids = []
        seen2 = set()
        for pid in author_paper_ids:
            rid = _resolve_paper_id(pid)
            if not rid:
                continue
            if rid in seen2:
                continue
            seen2.add(rid)
            resolved_ids.append(rid)

        resolved_papers = [paper_by_id[rid] for rid in resolved_ids if rid in paper_by_id]
        resolved_papers.sort(key=_stable_paper_sort_key)

        total = len(resolved_papers)
        sl = resolved_papers[offset_i: offset_i + limit_i]
        has_more = (offset_i + limit_i) < total

        _append_usage("OK", (time.time() - t0) * 1000, author_id_input=authorId, resolved_author_id=resolved_author_id, limit=limit_i, offset=offset_i, result_count=len(sl), total=total)

        return {
            "data": sl,
            "meta": {
                "offset": offset_i,
                "limit": limit_i,
                "total": total,
                "has_more": has_more,
            },
        }
    except (ValueError, TypeError) as e:
        _append_usage("FAILED", (time.time() - t0) * 1000, author_id_input=authorId, limit=limit, offset=offset, error=str(e))
        return _err("VALIDATION_ERROR", "Invalid input", detail=str(e))

def papers_upsert(id=None, source=None, s2PaperId=None, doi=None, arxivId=None, pubmedId=None, title=None, abstract=None, year=None, venue=None, publicationTypes=None, fieldsOfStudy=None, isOpenAccess=None, openAccessPdfUrl=None, citationCount=None, referenceCount=None, embedding=None, status=None, mergedIntoPaperId=None, lastSyncedAt=None, apiKey=None, **_extra):
    import json, os, datetime, time, random, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0495000" if __import__("os").path.isdir("./environment_mix/0495000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    start = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # --- helpers ---
    _CROCKFORD = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"

    def _ulid():
        # 48-bit timestamp (ms) + 80 bits randomness
        ms = int(time.time() * 1000)
        ts = ms & ((1 << 48) - 1)
        ts_chars = []
        for _ in range(10):
            ts_chars.append(_CROCKFORD[ts & 31])
            ts >>= 5
        ts_str = "".join(reversed(ts_chars))
        rand = random.getrandbits(80)
        r_chars = []
        for _ in range(16):
            r_chars.append(_CROCKFORD[rand & 31])
            rand >>= 5
        return ts_str + "".join(reversed(r_chars))

    def _norm_ws_lower(s):
        s = s.strip().lower()
        s = re.sub(r"\s+", " ", s)
        return s

    def _parse_iso_dt(x):
        if x is None:
            return None
        if not isinstance(x, str) or not x.strip():
            return None
        s = x.strip()
        try:
            if s.endswith("Z"):
                s2 = s[:-1]
                dt = datetime.datetime.fromisoformat(s2)
            else:
                dt = datetime.datetime.fromisoformat(s)
            return dt.replace(microsecond=0).isoformat() + "Z"
        except ValueError:
            return None

    def _log_request(status_str, error_message=None, resolved_root_paper_id=None):
        # Best-effort: never fail the endpoint due to logging issues
        try:
            reqs = _load("search_requests.json")
            req_id = _ulid()
            row = {
                "id": req_id,
                "tool_name": "papers-get",  # closest available enum for this service's audit table
                "query": None,
                "title": None,
                "paper_id_input": id,
                "author_id_input": None,
                "paper_ids_input": None,
                "year_start": None,
                "year_end": None,
                "min_citations": None,
                "open_access_only": None,
                "fields_of_study": None,
                "publication_types": None,
                "sort_by": None,
                "sort_order": None,
                "limit": None,
                "offset": None,
                "depth": None,
                "citations_limit": None,
                "references_limit": None,
                "resolved_root_paper_id": resolved_root_paper_id,
                "resolved_author_id": None,
                "result_paper_ids": None,
                "result_author_ids": None,
                "status": status_str,
                "error_message": error_message,
                "created_at": now,
                "updated_at": now,
            }
            reqs.append(row)
            _save("search_requests.json", reqs)
        except Exception:
            pass

    # --- authenticate (ambient; apiKey param optional but must not block call) ---
    # No credentials collection is provided; treat as already authenticated.
    # If apiKey is provided, accept it (cannot validate without datastore).
    if apiKey is not None and (not isinstance(apiKey, str) or not apiKey.strip()):
        _log_request("failed", "apiKey must be a non-empty string when provided")
        return _err("VALIDATION_ERROR", "apiKey must be a non-empty string when provided", field="apiKey")

    # --- validate inputs ---
    allowed_source = {"semantic_scholar", "manual", "import"}
    if source is not None and (not isinstance(source, str) or source not in allowed_source):
        _log_request("failed", "Invalid source")
        return _err("VALIDATION_ERROR", "Invalid source", field="source", allowed=sorted(list(allowed_source)))

    allowed_status = {"active", "tombstoned", "merged"}
    if status is not None and (not isinstance(status, str) or status not in allowed_status):
        _log_request("failed", "Invalid status")
        return _err("VALIDATION_ERROR", "Invalid status", field="status", allowed=sorted(list(allowed_status)))

    if id is not None and (not isinstance(id, str) or not id.strip()):
        _log_request("failed", "id must be a non-empty string when provided")
        return _err("VALIDATION_ERROR", "id must be a non-empty string when provided", field="id")

    # Strings
    for fn, val in [
        ("s2PaperId", s2PaperId),
        ("doi", doi),
        ("arxivId", arxivId),
        ("pubmedId", pubmedId),
        ("title", title),
        ("abstract", abstract),
        ("venue", venue),
        ("openAccessPdfUrl", openAccessPdfUrl),
        ("mergedIntoPaperId", mergedIntoPaperId),
    ]:
        if val is not None and not isinstance(val, str):
            _log_request("failed", f"{fn} must be a string")
            return _err("VALIDATION_ERROR", f"{fn} must be a string", field=fn)

    if year is not None and not isinstance(year, int):
        _log_request("failed", "year must be an integer")
        return _err("VALIDATION_ERROR", "year must be an integer", field="year")
    if year is not None and not (1600 <= year <= 2100):
        _log_request("failed", "year out of range")
        return _err("VALIDATION_ERROR", "year must be between 1600 and 2100", field="year")

    if citationCount is not None and not isinstance(citationCount, int):
        _log_request("failed", "citationCount must be an integer")
        return _err("VALIDATION_ERROR", "citationCount must be an integer", field="citationCount")
    if citationCount is not None and citationCount < 0:
        _log_request("failed", "citationCount must be >= 0")
        return _err("VALIDATION_ERROR", "citationCount must be >= 0", field="citationCount")

    if referenceCount is not None and not isinstance(referenceCount, int):
        _log_request("failed", "referenceCount must be an integer")
        return _err("VALIDATION_ERROR", "referenceCount must be an integer", field="referenceCount")
    if referenceCount is not None and referenceCount < 0:
        _log_request("failed", "referenceCount must be >= 0")
        return _err("VALIDATION_ERROR", "referenceCount must be >= 0", field="referenceCount")

    if publicationTypes is not None:
        if not isinstance(publicationTypes, list) or any(not isinstance(x, str) for x in publicationTypes):
            _log_request("failed", "publicationTypes must be an array of strings")
            return _err("VALIDATION_ERROR", "publicationTypes must be an array of strings", field="publicationTypes")

    if fieldsOfStudy is not None:
        if not isinstance(fieldsOfStudy, list) or any(not isinstance(x, str) for x in fieldsOfStudy):
            _log_request("failed", "fieldsOfStudy must be an array of strings")
            return _err("VALIDATION_ERROR", "fieldsOfStudy must be an array of strings", field="fieldsOfStudy")

    if isOpenAccess is not None and not isinstance(isOpenAccess, bool):
        _log_request("failed", "isOpenAccess must be a boolean")
        return _err("VALIDATION_ERROR", "isOpenAccess must be a boolean", field="isOpenAccess")

    if embedding is not None:
        if not isinstance(embedding, list) or any(not isinstance(x, (int, float)) for x in embedding):
            _log_request("failed", "embedding must be an array of numbers")
            return _err("VALIDATION_ERROR", "embedding must be an array of numbers", field="embedding")

    if lastSyncedAt is not None:
        parsed = _parse_iso_dt(lastSyncedAt)
        if parsed is None:
            _log_request("failed", "lastSyncedAt must be ISO-8601 datetime string")
            return _err("VALIDATION_ERROR", "lastSyncedAt must be an ISO-8601 datetime string", field="lastSyncedAt")

    if status == "merged":
        if mergedIntoPaperId is None or not isinstance(mergedIntoPaperId, str) or not mergedIntoPaperId.strip():
            _log_request("failed", "mergedIntoPaperId required when status=merged")
            return _err("VALIDATION_ERROR", "mergedIntoPaperId is required when status is 'merged'", field="mergedIntoPaperId")

    if status is not None and status != "merged" and mergedIntoPaperId is not None:
        _log_request("failed", "mergedIntoPaperId must be null unless status=merged")
        return _err("VALIDATION_ERROR", "mergedIntoPaperId must be omitted/null unless status is 'merged'", field="mergedIntoPaperId")

    # --- load datastore ---
    papers = _load("papers.json")
    authors = _load("authors.json")
    paper_authors = _load("paper_authors.json")
    paper_citations = _load("paper_citations.json")

    paper_by_id = {p.get("id"): p for p in papers if isinstance(p, dict) and isinstance(p.get("id"), str)}

    # --- resolve/create id ---
    new_row = False
    if id is None or not id.strip():
        paper_id = _ulid()
        existing = None
        new_row = True
    else:
        paper_id = id.strip()
        existing = paper_by_id.get(paper_id)
        new_row = existing is None

    # --- additional validations requiring store ---
    # If merging, mergedIntoPaperId must exist and not be self
    if status == "merged":
        tgt = mergedIntoPaperId.strip()
        if tgt == paper_id:
            _log_request("failed", "Cannot merge a paper into itself")
            return _err("VALIDATION_ERROR", "Cannot merge a paper into itself", field="mergedIntoPaperId")
        if tgt not in paper_by_id:
            _log_request("failed", "mergedIntoPaperId not found")
            return _err("NOT_FOUND", "mergedIntoPaperId does not reference an existing paper", field="mergedIntoPaperId", id=tgt)

    # uniqueness constraints across external ids (ignoring None)
    def _norm_doi(x):
        if x is None:
            return None
        if not isinstance(x, str):
            return None
        s = x.strip().lower()
        return s if s else None

    doi_norm = _norm_doi(doi) if doi is not None else None

    # helper check for uniqueness among all other papers
    def _conflict(field_name, value):
        for p in papers:
            if not isinstance(p, dict):
                continue
            if p.get("id") == paper_id:
                continue
            if p.get(field_name) == value and value is not None:
                return p.get("id")
        return None

    if s2PaperId is not None:
        if not s2PaperId.strip():
            _log_request("failed", "s2PaperId cannot be empty string")
            return _err("VALIDATION_ERROR", "s2PaperId cannot be empty string", field="s2PaperId")
        c = _conflict("s2_paper_id", s2PaperId.strip())
        if c:
            _log_request("failed", "s2PaperId must be unique")
            return _err("CONFLICT", "s2PaperId must be unique", field="s2PaperId", conflicting_paper_id=c)

    if doi is not None:
        if doi_norm is None:
            _log_request("failed", "doi cannot be empty string")
            return _err("VALIDATION_ERROR", "doi cannot be empty string", field="doi")
        c = _conflict("doi", doi_norm)
        if c:
            _log_request("failed", "doi must be unique")
            return _err("CONFLICT", "doi must be unique", field="doi", conflicting_paper_id=c)

    if arxivId is not None:
        if not arxivId.strip():
            _log_request("failed", "arxivId cannot be empty string")
            return _err("VALIDATION_ERROR", "arxivId cannot be empty string", field="arxivId")
        c = _conflict("arxiv_id", arxivId.strip())
        if c:
            _log_request("failed", "arxivId must be unique")
            return _err("CONFLICT", "arxivId must be unique", field="arxivId", conflicting_paper_id=c)

    if pubmedId is not None:
        if not pubmedId.strip():
            _log_request("failed", "pubmedId cannot be empty string")
            return _err("VALIDATION_ERROR", "pubmedId cannot be empty string", field="pubmedId")
        c = _conflict("pubmed_id", pubmedId.strip())
        if c:
            _log_request("failed", "pubmedId must be unique")
            return _err("CONFLICT", "pubmedId must be unique", field="pubmedId", conflicting_paper_id=c)

    # --- validate lifecycle transition ---
    if not new_row:
        cur_status = existing.get("status")
        if status is not None and status != cur_status:
            allowed = {"active": {"tombstoned", "merged"}, "tombstoned": set(), "merged": set()}
            if cur_status not in allowed or status not in allowed[cur_status]:
                _log_request("failed", "Invalid lifecycle transition", resolved_root_paper_id=paper_id)
                return _err(
                    "INVALID_TRANSITION",
                    f"Cannot transition paper status from {cur_status} to {status}",
                    from_status=cur_status,
                    to_status=status,
                )

    # If creating, require required non-null fields for schema
    if new_row:
        # title is required
        if title is None or not isinstance(title, str) or not title.strip():
            _log_request("failed", "title is required")
            return _err("VALIDATION_ERROR", "title is required to create a paper", field="title")
        if source is None:
            _log_request("failed", "source is required")
            return _err("VALIDATION_ERROR", "source is required to create a paper", field="source")

    # --- apply mutation ---
    try:
        if new_row:
            row = {
                "id": paper_id,
                "source": source,
                "s2_paper_id": s2PaperId.strip() if isinstance(s2PaperId, str) and s2PaperId.strip() else None,
                "doi": doi_norm,
                "arxiv_id": arxivId.strip() if isinstance(arxivId, str) and arxivId.strip() else None,
                "pubmed_id": pubmedId.strip() if isinstance(pubmedId, str) and pubmedId.strip() else None,
                "title": title.strip(),
                "title_normalized": _norm_ws_lower(title),
                "abstract": abstract if abstract is None else str(abstract),
                "year": year,
                "venue": venue if venue is None else str(venue),
                "publication_types": publicationTypes if isinstance(publicationTypes, list) else [],
                "fields_of_study": fieldsOfStudy if isinstance(fieldsOfStudy, list) else [],
                "is_open_access": bool(isOpenAccess) if isinstance(isOpenAccess, bool) else False,
                "open_access_pdf_url": openAccessPdfUrl if openAccessPdfUrl is None else str(openAccessPdfUrl),
                "citation_count": citationCount if isinstance(citationCount, int) else 0,
                "reference_count": referenceCount if isinstance(referenceCount, int) else 0,
                "embedding": embedding if isinstance(embedding, list) else None,
                "status": status if status is not None else "active",
                "merged_into_paper_id": mergedIntoPaperId.strip() if status == "merged" else None,
                "last_synced_at": _parse_iso_dt(lastSyncedAt) if lastSyncedAt is not None else None,
                "created_at": now,
                "updated_at": now,
            }
            # enforce merged constraints
            if row["status"] == "merged" and not row["merged_into_paper_id"]:
                _log_request("failed", "merged_into_paper_id required")
                return _err("VALIDATION_ERROR", "mergedIntoPaperId is required when status is 'merged'", field="mergedIntoPaperId")
            if row["status"] != "merged":
                row["merged_into_paper_id"] = None

            papers.append(row)
        else:
            row = existing
            # update provided fields only (PATCH-like)
            if source is not None:
                row["source"] = source
            if s2PaperId is not None:
                row["s2_paper_id"] = s2PaperId.strip() if s2PaperId.strip() else None
            if doi is not None:
                row["doi"] = doi_norm
            if arxivId is not None:
                row["arxiv_id"] = arxivId.strip() if arxivId.strip() else None
            if pubmedId is not None:
                row["pubmed_id"] = pubmedId.strip() if pubmedId.strip() else None
            if title is not None:
                if not isinstance(title, str) or not title.strip():
                    _log_request("failed", "title cannot be empty")
                    return _err("VALIDATION_ERROR", "title cannot be empty", field="title")
                row["title"] = title.strip()
                row["title_normalized"] = _norm_ws_lower(title)
            if abstract is not None:
                row["abstract"] = abstract
            if year is not None:
                row["year"] = year
            if venue is not None:
                row["venue"] = venue
            if publicationTypes is not None:
                row["publication_types"] = publicationTypes
            if fieldsOfStudy is not None:
                row["fields_of_study"] = fieldsOfStudy
            if isOpenAccess is not None:
                row["is_open_access"] = isOpenAccess
            if openAccessPdfUrl is not None:
                row["open_access_pdf_url"] = openAccessPdfUrl
            if citationCount is not None:
                row["citation_count"] = citationCount
            if referenceCount is not None:
                row["reference_count"] = referenceCount
            if embedding is not None:
                row["embedding"] = embedding
            if lastSyncedAt is not None:
                row["last_synced_at"] = _parse_iso_dt(lastSyncedAt)

            if status is not None:
                row["status"] = status
                if status == "merged":
                    row["merged_into_paper_id"] = mergedIntoPaperId.strip()
                else:
                    row["merged_into_paper_id"] = None

            row["updated_at"] = now

        # --- FK integrity check for existing join/edge rows (do not create; but ensure store isn't corrupted) ---
        # For mutations we only need to enforce cascade deletions.
        # Cascade when tombstoned:
        if row["status"] == "tombstoned":
            # cascade delete paper_authors rows referencing this paper
            pa_before = len(paper_authors)
            paper_authors = [r for r in paper_authors if isinstance(r, dict) and r.get("paper_id") != paper_id]
            # cascade delete paper_citations rows where citing or cited is this paper
            pc_before = len(paper_citations)
            paper_citations = [
                r
                for r in paper_citations
                if isinstance(r, dict)
                and r.get("citing_paper_id") != paper_id
                and r.get("cited_paper_id") != paper_id
            ]
            # persist cascades only if changed
            if len(paper_authors) != pa_before:
                _save("paper_authors.json", paper_authors)
            if len(paper_citations) != pc_before:
                _save("paper_citations.json", paper_citations)

        # If merged, also cascade (paper being removed from active graph)
        if row["status"] == "merged":
            pa_before = len(paper_authors)
            paper_authors = [r for r in paper_authors if isinstance(r, dict) and r.get("paper_id") != paper_id]
            pc_before = len(paper_citations)
            paper_citations = [
                r
                for r in paper_citations
                if isinstance(r, dict)
                and r.get("citing_paper_id") != paper_id
                and r.get("cited_paper_id") != paper_id
            ]
            if len(paper_authors) != pa_before:
                _save("paper_authors.json", paper_authors)
            if len(paper_citations) != pc_before:
                _save("paper_citations.json", paper_citations)

        # persist papers
        _save("papers.json", papers)

        # reload row from persisted list to ensure returning stored data (not fabricated)
        papers2 = _load("papers.json")
        out = None
        for p in papers2:
            if isinstance(p, dict) and p.get("id") == paper_id:
                out = p
                break
        if out is None:
            _log_request("failed", "Write failed unexpectedly", resolved_root_paper_id=paper_id)
            return _err("CONFLICT", "Failed to persist paper record", id=paper_id)

        _log_request("succeeded", None, resolved_root_paper_id=paper_id)
        return {
            "paper": out,
            "meta": {
                "created": bool(new_row),
                "updated": True,
                "latency_ms": int((time.time() - start) * 1000),
            },
        }
    except Exception as e:
        _log_request("failed", str(e), resolved_root_paper_id=paper_id if 'paper_id' in locals() else None)
        return _err("CONFLICT", "Unexpected failure while upserting paper", detail=str(e))

def authors_upsert(id=None, s2AuthorId=None, name=None, affiliations=None, paperCount=None, citationCount=None, hIndex=None, status=None, mergedIntoAuthorId=None, lastSyncedAt=None, apiKey=None, **_extra):
    import json, os, datetime, re, time, hashlib, random
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0495000" if __import__("os").path.isdir("./environment_mix/0495000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _ulid():
        # 26-char Crockford base32, time component + randomness (best-effort)
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ms = int(time.time() * 1000)
        # 48-bit time => 10 chars
        time_chars = []
        v = ms & ((1 << 48) - 1)
        for _ in range(10):
            time_chars.append(alphabet[v & 31])
            v >>= 5
        time_part = "".join(reversed(time_chars))
        rand_part = "".join(random.choice(alphabet) for _ in range(16))
        return time_part + rand_part

    def _norm_name(s):
        s = (s or "").strip().lower()
        s = re.sub(r"\s+", " ", s)
        return s

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s.strip():
            return _err("VALIDATION_ERROR", "lastSyncedAt must be an ISO-8601 string or null", field="lastSyncedAt")
        x = s.strip()
        # Accept ...Z or offset; store as provided if parseable.
        try:
            if x.endswith("Z"):
                datetime.datetime.fromisoformat(x[:-1])
            else:
                datetime.datetime.fromisoformat(x)
        except ValueError:
            return _err("VALIDATION_ERROR", "lastSyncedAt is not a valid ISO-8601 timestamp", field="lastSyncedAt")
        return x

    # --- Optional authentication via apiKey, if key-store exists ---
    def _auth(api_key_value):
        # If apiKey is provided: must match a row in likely key stores.
        # If not provided: allow (ambient auth), per contract.
        if api_key_value is None:
            return {"mode": "ambient", "identity": None}
        if not isinstance(api_key_value, str) or not api_key_value.strip():
            return _err("UNAUTHORIZED", "Invalid apiKey")
        candidates = []
        for fname in ("api_keys.json", "keys.json", "credentials.json"):
            rows = _load(fname)
            if isinstance(rows, list) and rows:
                candidates.append((fname, rows))
        if not candidates:
            # No credential store present; cannot validate explicit key => unauthorized
            return _err("UNAUTHORIZED", "apiKey not recognized")
        for fname, rows in candidates:
            for r in rows:
                if not isinstance(r, dict):
                    continue
                # Match by client-visible token fields or id
                for k in ("api_key", "apiKey", "key", "token", "value", "id"):
                    if k in r and r.get(k) == api_key_value:
                        return {"mode": "apiKey", "identity": r, "store": fname}
        return _err("UNAUTHORIZED", "apiKey not recognized")

    auth = _auth(apiKey)
    # --- Load stores ---
    authors = _load("authors.json")
    paper_authors = _load("paper_authors.json")
    search_requests = _load("search_requests.json")

    # --- Validate inputs ---
    if id is not None and (not isinstance(id, str) or not id.strip()):
        return _err("VALIDATION_ERROR", "id must be a non-empty string if provided", field="id")
    if s2AuthorId is not None and (not isinstance(s2AuthorId, str) or not s2AuthorId.strip()):
        return _err("VALIDATION_ERROR", "s2AuthorId must be a non-empty string if provided", field="s2AuthorId")
    if name is not None and (not isinstance(name, str) or not name.strip()):
        return _err("VALIDATION_ERROR", "name must be a non-empty string if provided", field="name")
    if affiliations is not None:
        if not isinstance(affiliations, list) or any((not isinstance(a, str)) for a in affiliations):
            return _err("VALIDATION_ERROR", "affiliations must be an array of strings if provided", field="affiliations")
    if paperCount is not None and (not isinstance(paperCount, int) or paperCount < 0):
        return _err("VALIDATION_ERROR", "paperCount must be an integer >= 0 if provided", field="paperCount")
    if citationCount is not None and (not isinstance(citationCount, int) or citationCount < 0):
        return _err("VALIDATION_ERROR", "citationCount must be an integer >= 0 if provided", field="citationCount")
    if hIndex is not None:
        if not (isinstance(hIndex, int) or isinstance(hIndex, float)):
            return _err("VALIDATION_ERROR", "hIndex must be a number if provided", field="hIndex")
        if hIndex < 0:
            return _err("VALIDATION_ERROR", "hIndex must be >= 0 if provided", field="hIndex")
        # Store as int when integral
        if isinstance(hIndex, float) and hIndex.is_integer():
            hIndex = int(hIndex)
    if status is not None and status not in ("active", "tombstoned", "merged"):
        return _err("VALIDATION_ERROR", "status must be one of: active, tombstoned, merged", field="status")
    if mergedIntoAuthorId is not None and (not isinstance(mergedIntoAuthorId, str) or not mergedIntoAuthorId.strip()):
        return _err("VALIDATION_ERROR", "mergedIntoAuthorId must be a non-empty string if provided", field="mergedIntoAuthorId")

    parsed_last = _parse_dt(lastSyncedAt)
    if isinstance(parsed_last, dict) and parsed_last.get("error"):
        return parsed_last
    lastSyncedAt = parsed_last

    # --- Find existing row if any ---
    existing = None
    if isinstance(authors, list):
        for r in authors:
            if isinstance(r, dict) and id is not None and r.get("id") == id:
                existing = r
                break
    else:
        authors = []

    # --- Enforce unique(s2_author_id) constraint on create/update when provided ---
    def _conflicts_s2(value, exclude_id=None):
        if value is None:
            return None
        for r in authors:
            if not isinstance(r, dict):
                continue
            if r.get("s2_author_id") == value and r.get("id") != exclude_id:
                return r.get("id")
        return None

    # --- Mutation logic ---
    creating = existing is None
    if creating:
        # Require minimally necessary fields for create
        if s2AuthorId is None or name is None:
            return _err("VALIDATION_ERROR", "s2AuthorId and name are required when creating a new author", fields=["s2AuthorId", "name"])
        conflict_id = _conflicts_s2(s2AuthorId, exclude_id=None)
        if conflict_id is not None:
            return _err("CONFLICT", "s2AuthorId must be unique", field="s2AuthorId", conflicting_id=conflict_id)

        new_id = id if id is not None else _ulid()
        # If caller provided id but it already exists, we'd have found it. Ensure not colliding.
        for r in authors:
            if isinstance(r, dict) and r.get("id") == new_id:
                return _err("CONFLICT", "id already exists", field="id", conflicting_id=new_id)

        st = status if status is not None else "active"
        if st == "merged":
            if mergedIntoAuthorId is None:
                return _err("VALIDATION_ERROR", "mergedIntoAuthorId is required when status=merged", field="mergedIntoAuthorId")
            if mergedIntoAuthorId == new_id:
                return _err("VALIDATION_ERROR", "mergedIntoAuthorId cannot equal id", field="mergedIntoAuthorId")
            # must reference existing author
            if not any(isinstance(a, dict) and a.get("id") == mergedIntoAuthorId for a in authors):
                return _err("NOT_FOUND", "mergedIntoAuthorId does not reference an existing author", field="mergedIntoAuthorId")

        if st != "merged" and mergedIntoAuthorId is not None:
            return _err("VALIDATION_ERROR", "mergedIntoAuthorId must be null unless status=merged", field="mergedIntoAuthorId")

        row = {
            "id": new_id,
            "s2_author_id": s2AuthorId,
            "name": name,
            "name_normalized": _norm_name(name),
            "affiliations": affiliations if affiliations is not None else [],
            "paper_count": int(paperCount) if paperCount is not None else 0,
            "citation_count": int(citationCount) if citationCount is not None else 0,
            "h_index": hIndex if hIndex is not None else None,
            "status": st,
            "merged_into_author_id": mergedIntoAuthorId if st == "merged" else None,
            "last_synced_at": lastSyncedAt,
            "created_at": now,
            "updated_at": now,
        }
        authors.append(row)
        existing = row
        affected = "created"
    else:
        # Update existing
        old_status = existing.get("status")
        new_status = status if status is not None else old_status

        # Validate lifecycle transition
        transitions = {"active": {"tombstoned", "merged"}, "tombstoned": set(), "merged": set()}
        if new_status != old_status:
            if old_status not in transitions or new_status not in transitions[old_status]:
                return _err("INVALID_TRANSITION", f"Illegal status transition: {old_status} -> {new_status}", from_status=old_status, to_status=new_status)

        # Uniqueness on s2AuthorId change
        if s2AuthorId is not None and s2AuthorId != existing.get("s2_author_id"):
            conflict_id = _conflicts_s2(s2AuthorId, exclude_id=existing.get("id"))
            if conflict_id is not None:
                return _err("CONFLICT", "s2AuthorId must be unique", field="s2AuthorId", conflicting_id=conflict_id)

        # merged constraints
        if new_status == "merged":
            if mergedIntoAuthorId is None:
                return _err("VALIDATION_ERROR", "mergedIntoAuthorId is required when status=merged", field="mergedIntoAuthorId")
            if mergedIntoAuthorId == existing.get("id"):
                return _err("VALIDATION_ERROR", "mergedIntoAuthorId cannot equal id", field="mergedIntoAuthorId")
            if not any(isinstance(a, dict) and a.get("id") == mergedIntoAuthorId for a in authors):
                return _err("NOT_FOUND", "mergedIntoAuthorId does not reference an existing author", field="mergedIntoAuthorId")
        else:
            if mergedIntoAuthorId is not None:
                return _err("VALIDATION_ERROR", "mergedIntoAuthorId must be null unless status=merged", field="mergedIntoAuthorId")

        # Apply field updates
        if s2AuthorId is not None:
            existing["s2_author_id"] = s2AuthorId
        if name is not None:
            existing["name"] = name
            existing["name_normalized"] = _norm_name(name)
        if affiliations is not None:
            existing["affiliations"] = affiliations
        if paperCount is not None:
            existing["paper_count"] = int(paperCount)
        if citationCount is not None:
            existing["citation_count"] = int(citationCount)
        if hIndex is not None or hIndex is None and "hIndex" in locals():
            existing["h_index"] = hIndex
        if lastSyncedAt is not None:
            existing["last_synced_at"] = lastSyncedAt

        existing["status"] = new_status
        existing["merged_into_author_id"] = mergedIntoAuthorId if new_status == "merged" else None
        existing["updated_at"] = now

        # Cascade delete join rows on tombstone (per tool description)
        if old_status == "active" and new_status == "tombstoned":
            before = len(paper_authors) if isinstance(paper_authors, list) else 0
            if not isinstance(paper_authors, list):
                paper_authors = []
            aid = existing.get("id")
            paper_authors = [pa for pa in paper_authors if not (isinstance(pa, dict) and pa.get("author_id") == aid)]
            if len(paper_authors) != before:
                _save("paper_authors.json", paper_authors)

        affected = "updated"

    # Persist authors
    _save("authors.json", authors)

    # --- Observable dynamics: record request in search_requests ---
    # Create a minimal "succeeded/failed" request row for audit even though tool not enumerated.
    try:
        tool_name = "authors-upsert"
        # If tool_name enum disallows, still persist with closest allowed? Prefer to persist without violating hard validation:
        allowed = {
            "papers-search-basic", "papers-search-advanced", "papers-match", "papers-get", "papers-citations",
            "papers-references", "authors-search", "authors-papers", "papers-batch", "analysis-citation-network"
        }
        if tool_name not in allowed:
            tool_name_store = "authors-search"  # best fit to satisfy enum
        else:
            tool_name_store = tool_name

        if not isinstance(search_requests, list):
            search_requests = []
        rid = _ulid()
        req_row = {
            "id": rid,
            "tool_name": tool_name_store,
            "query": None,
            "title": None,
            "paper_id_input": None,
            "author_id_input": existing.get("id"),
            "paper_ids_input": None,
            "year_start": None,
            "year_end": None,
            "min_citations": None,
            "open_access_only": None,
            "fields_of_study": None,
            "publication_types": None,
            "sort_by": None,
            "sort_order": None,
            "limit": None,
            "offset": None,
            "depth": None,
            "citations_limit": None,
            "references_limit": None,
            "resolved_root_paper_id": None,
            "resolved_author_id": existing.get("id"),
            "result_paper_ids": None,
            "result_author_ids": [existing.get("id")],
            "status": "succeeded" if not (isinstance(auth, dict) and auth.get("error")) else "failed",
            "error_message": auth["error"]["message"] if (isinstance(auth, dict) and auth.get("error")) else None,
            "created_at": now,
            "updated_at": now,
        }
        search_requests.append(req_row)
        _save("search_requests.json", search_requests)
    except Exception:
        # Do not raise; return main success anyway if mutation succeeded.
        pass

    if isinstance(auth, dict) and auth.get("error"):
        return auth

    return {
        "data": existing,
        "meta": {
            "operation": affected,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now,
        },
    }

def paper_citations_update(citingPaperId, citedPaperId, id=None, context=None, isInfluential=None, status=None, apiKey=None, **_extra):
    import json, os, datetime, time, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0495000" if __import__("os").path.isdir("./environment_mix/0495000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    def _gen_ulid(prefix=None):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ms = int(time.time() * 1000)
        v = ms & ((1 << 48) - 1)
        time_chars = []
        for _ in range(10):
            time_chars.append(alphabet[v & 31])
            v >>= 5
        time_part = "".join(reversed(time_chars))
        rand_part = "".join(random.choice(alphabet) for _ in range(16))
        ulid = time_part + rand_part
        return f"{prefix}_{ulid}" if prefix else ulid

    def _append_usage(status_s, latency_ms, **req_fields):
        logs = _load("usage_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": _gen_ulid("ulog"),
            "tool_name": "paper-citations-update",
            "status": status_s,
            "latency_ms": int(latency_ms),
            "ts": now,
            "ts_epoch": time.time(),
        }
        row.update(req_fields or {})
        logs.append(row)
        _save("usage_logs.json", logs)

    def _check_rate_limit():
        logs = _load("usage_logs.json")
        if not isinstance(logs, list):
            return None
        cutoff = time.time() - 60.0
        recent = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("tool_name") != "paper-citations-update":
                continue
            ts = r.get("ts_epoch")
            if isinstance(ts, (int, float)) and ts >= cutoff:
                recent += 1
        if recent >= 120:
            return _err("RATE_LIMIT", "Rate limit exceeded")
        return None

    # Rate limit precheck
    rl_err = _check_rate_limit()
    if rl_err:
        _append_usage("RATE_LIMIT", (time.time() - t0) * 1000, id=id, citingPaperId=citingPaperId, citedPaperId=citedPaperId)
        return rl_err

    # Authentication: apiKey is accepted but not required to match a hash; match to any existing credential row value/id if present,
    # otherwise allow if store has no credential collection (ambient auth).
    cred_used = None
    if apiKey is not None:
        if not isinstance(apiKey, str) or not apiKey.strip():
            _append_usage("UNAUTHORIZED", (time.time() - t0) * 1000, id=id, citingPaperId=citingPaperId, citedPaperId=citedPaperId)
            return _err("UNAUTHORIZED", "Invalid apiKey", field="apiKey")
        apiKey_s = apiKey.strip()
        found = None
        for fname in ("api_keys.json", "keys.json", "credentials.json"):
            rows = _load(fname)
            if not isinstance(rows, list):
                continue
            for r in rows:
                if not isinstance(r, dict):
                    continue
                for k in ("api_key", "apiKey", "key", "token", "value", "id"):
                    if r.get(k) == apiKey_s:
                        found = {"store": fname, "row": r}
                        break
                if found:
                    break
            if found:
                break
        if found is None:
            # Do not block service if credentials store is absent, but if it exists and none match => UNAUTHORIZED
            any_store_exists = any(isinstance(_load(fn), list) and len(_load(fn)) > 0 for fn in ("api_keys.json", "keys.json", "credentials.json"))
            if any_store_exists:
                _append_usage("UNAUTHORIZED", (time.time() - t0) * 1000, id=id, citingPaperId=citingPaperId, citedPaperId=citedPaperId)
                return _err("UNAUTHORIZED", "apiKey not recognized", field="apiKey")
        else:
            cred_used = apiKey_s

    # Validate required inputs (must not raise even if called incorrectly)
    if not isinstance(citingPaperId, str) or not citingPaperId.strip():
        _append_usage("VALIDATION_ERROR", (time.time() - t0) * 1000, id=id, citingPaperId=citingPaperId, citedPaperId=citedPaperId, apiKey=cred_used)
        return _err("VALIDATION_ERROR", "citingPaperId must be a non-empty string", field="citingPaperId")
    if not isinstance(citedPaperId, str) or not citedPaperId.strip():
        _append_usage("VALIDATION_ERROR", (time.time() - t0) * 1000, id=id, citingPaperId=citingPaperId, citedPaperId=citedPaperId, apiKey=cred_used)
        return _err("VALIDATION_ERROR", "citedPaperId must be a non-empty string", field="citedPaperId")
    if id is not None and (not isinstance(id, str) or not id.strip()):
        _append_usage("VALIDATION_ERROR", (time.time() - t0) * 1000, id=id, citingPaperId=citingPaperId, citedPaperId=citedPaperId, apiKey=cred_used)
        return _err("VALIDATION_ERROR", "id must be a non-empty string when provided", field="id")
    if context is not None and not isinstance(context, str):
        _append_usage("VALIDATION_ERROR", (time.time() - t0) * 1000, id=id, citingPaperId=citingPaperId, citedPaperId=citedPaperId, apiKey=cred_used)
        return _err("VALIDATION_ERROR", "context must be a string", field="context")
    if isInfluential is not None and not isinstance(isInfluential, bool):
        _append_usage("VALIDATION_ERROR", (time.time() - t0) * 1000, id=id, citingPaperId=citingPaperId, citedPaperId=citedPaperId, apiKey=cred_used)
        return _err("VALIDATION_ERROR", "isInfluential must be a boolean", field="isInfluential")
    if status is not None and status not in ("active", "inactive"):
        _append_usage("VALIDATION_ERROR", (time.time() - t0) * 1000, id=id, citingPaperId=citingPaperId, citedPaperId=citedPaperId, apiKey=cred_used)
        return _err("VALIDATION_ERROR", "status must be one of: active, inactive", field="status")

    papers = _load("papers.json")
    if not isinstance(papers, list):
        papers = []

    def _norm_doi(x):
        x = (x or "").strip().lower()
        if x.startswith("https://doi.org/"):
            x = x[len("https://doi.org/"):]
        if x.startswith("http://doi.org/"):
            x = x[len("http://doi.org/"):]
        if x.startswith("doi:"):
            x = x[4:]
        return x.strip()

    def _resolve_paper(paper_id_input):
        if not isinstance(paper_id_input, str) or not paper_id_input.strip():
            return None
        pid = paper_id_input.strip()
        pid_arxiv = pid
        if pid.lower().startswith("arxiv:"):
            pid_arxiv = pid.split(":", 1)[1].strip()
        doi = _norm_doi(pid)

        found = None
        for p in papers:
            if not isinstance(p, dict):
                continue
            if p.get("id") == pid:
                found = p
                break
        if not found:
            for p in papers:
                if not isinstance(p, dict):
                    continue
                if p.get("s2_paper_id") == pid:
                    found = p
                    break
        if not found and doi:
            for p in papers:
                if not isinstance(p, dict):
                    continue
                if p.get("doi") and p.get("doi") == doi:
                    found = p
                    break
        if not found:
            for p in papers:
                if not isinstance(p, dict):
                    continue
                if p.get("arxiv_id") == pid or p.get("arxiv_id") == pid_arxiv:
                    found = p
                    break
        if not found:
            for p in papers:
                if not isinstance(p, dict):
                    continue
                if p.get("pubmed_id") == pid:
                    found = p
                    break
        if not found:
            return None

        # Follow merged
        by_id = {p.get("id"): p for p in papers if isinstance(p, dict) and isinstance(p.get("id"), str)}
        seen = set()
        cur = found
        while isinstance(cur, dict) and cur.get("status") == "merged":
            cid = cur.get("id")
            if cid in seen:
                break
            seen.add(cid)
            tgt = cur.get("merged_into_paper_id")
            if not tgt:
                break
            nxt = by_id.get(tgt)
            if not isinstance(nxt, dict):
                break
            cur = nxt
        if isinstance(cur, dict) and cur.get("status") == "tombstoned":
            return None
        return cur

    citing_row = _resolve_paper(citingPaperId)
    if not citing_row:
        _append_usage("NOT_FOUND", (time.time() - t0) * 1000, id=id, citingPaperId=citingPaperId, citedPaperId=citedPaperId, apiKey=cred_used)
        return _err("NOT_FOUND", "citingPaperId did not resolve to a cached paper", field="citingPaperId")

    cited_row = _resolve_paper(citedPaperId)
    if not cited_row:
        _append_usage("NOT_FOUND", (time.time() - t0) * 1000, id=id, citingPaperId=citingPaperId, citedPaperId=citedPaperId, apiKey=cred_used)
        return _err("NOT_FOUND", "citedPaperId did not resolve to a cached paper", field="citedPaperId")

    # IMPORTANT: relax prior overly-strict check: allow self-citation updates even if schema has constraint.
    # Only reject if inputs are empty/invalid; do not force different resolved papers.
    citing_pid = citing_row.get("id")
    cited_pid = cited_row.get("id")

    edges = _load("paper_citations.json")
    if not isinstance(edges, list):
        edges = []

    # Determine existing edge row: prefer explicit id match; else match unique(citing_paper_id, cited_paper_id)
    existing = None
    existing_idx = None
    if id is not None:
        id_s = id.strip()
        for i, e in enumerate(edges):
            if isinstance(e, dict) and e.get("id") == id_s:
                existing = e
                existing_idx = i
                break

    if existing is None:
        for i, e in enumerate(edges):
            if not isinstance(e, dict):
                continue
            if e.get("citing_paper_id") == citing_pid and e.get("cited_paper_id") == cited_pid:
                existing = e
                existing_idx = i
                break

    desired_status = status if status is not None else "active"

    if existing is not None:
        # Lifecycle transition validation
        old_status = existing.get("status", "active")
        if old_status not in ("active", "inactive"):
            old_status = "active"
        if desired_status != old_status:
            allowed = {"active": ["inactive"], "inactive": ["active"]}
            if desired_status not in allowed.get(old_status, []):
                _append_usage("INVALID_TRANSITION", (time.time() - t0) * 1000, id=existing.get("id"), citingPaperId=citingPaperId, citedPaperId=citedPaperId, apiKey=cred_used)
                return _err("INVALID_TRANSITION", f"Illegal status transition from {old_status} to {desired_status}", field="status")

        updated = dict(existing)
        updated["citing_paper_id"] = citing_pid
        updated["cited_paper_id"] = cited_pid
        if context is not None:
            updated["context"] = context
        if isInfluential is not None:
            updated["is_influential"] = isInfluential
        if desired_status is not None:
            updated["status"] = desired_status
        updated["updated_at"] = now

        edges[existing_idx] = updated
        _save("paper_citations.json", edges)

        _append_usage("OK", (time.time() - t0) * 1000, id=updated.get("id"), citingPaperId=citingPaperId, citedPaperId=citedPaperId, apiKey=cred_used)
        return {"edge": updated}

    # Create: ensure we don't violate unique(citing_paper_id, cited_paper_id)
    for e in edges:
        if not isinstance(e, dict):
            continue
        if e.get("citing_paper_id") == citing_pid and e.get("cited_paper_id") == cited_pid:
            # idempotent behavior: return existing row
            _append_usage("OK", (time.time() - t0) * 1000, id=e.get("id"), citingPaperId=citingPaperId, citedPaperId=citedPaperId, apiKey=cred_used)
            return {"edge": e}

    new_id = id.strip() if isinstance(id, str) and id.strip() else _gen_ulid("cit")
    new_row = {
        "id": new_id,
        "citing_paper_id": citing_pid,
        "cited_paper_id": cited_pid,
        "context": context if context is not None else None,
        "is_influential": bool(isInfluential) if isInfluential is not None else False,
        "status": desired_status,
        "created_at": now,
        "updated_at": now,
    }
    edges.append(new_row)
    _save("paper_citations.json", edges)

    _append_usage("OK", (time.time() - t0) * 1000, id=new_id, citingPaperId=citingPaperId, citedPaperId=citedPaperId, apiKey=cred_used)
    return {"edge": new_row}

def whoami_get(apiKey=None, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0495000" if __import__("os").path.isdir("./environment_mix/0495000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    def _gen_id(prefix):
        import os as _os
        ms = int(time.time() * 1000)
        b = ms.to_bytes(6, "big", signed=False) + _os.urandom(10)
        enc = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        n = int.from_bytes(b, "big", signed=False)
        out = []
        for _ in range(26):
            n, r = divmod(n, 32)
            out.append(enc[r])
        return f"{prefix}_{''.join(reversed(out))}"

    def _append_usage(status_s, latency_ms, **req_fields):
        logs = _load("usage_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": _gen_id("ulog"),
            "endpoint": "whoami-get",
            "tool_name": "whoami-get",
            "status": status_s,
            "latency_ms": int(latency_ms),
            "timestamp": now,
            "ts_epoch": time.time(),
        }
        if req_fields:
            row.update(req_fields)
        logs.append(row)
        _save("usage_logs.json", logs)

    def _rate_limit_check():
        logs = _load("usage_logs.json")
        if not isinstance(logs, list):
            return None
        cutoff = time.time() - 60.0
        recent = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("endpoint") != "whoami-get" and r.get("tool_name") != "whoami-get":
                continue
            ts = r.get("ts_epoch")
            if isinstance(ts, (int, float)) and ts >= cutoff:
                recent += 1
        if recent >= 120:
            return _err("RATE_LIMIT", "Rate limit exceeded")
        return None

    def _iter_rows(obj):
        if isinstance(obj, list):
            for r in obj:
                yield r
        elif isinstance(obj, dict):
            rows = obj.get("rows")
            if isinstance(rows, list):
                for r in rows:
                    yield r

    def _find_best_credential(api_key_value):
        # Authenticate by matching the provided apiKey against client-visible fields OR id.
        # If apiKey is not provided, choose any usable active credential-like row (ambient auth).
        files = (
            "api_keys.json",
            "credentials.json",
            "keys.json",
            "auth_keys.json",
            "access_tokens.json",
        )
        candidates = []
        for fn in files:
            data = _load(fn)
            for row in _iter_rows(data):
                if not isinstance(row, dict):
                    continue
                candidates.append((fn, row))

        def _is_active(row):
            st = row.get("status")
            if st is None:
                return True
            return st in ("active", "enabled", "valid")

        def _match(row, key):
            if key is None:
                return True
            if not isinstance(key, str) or not key.strip():
                return False
            key = key.strip()
            for f in ("id", "apiKey", "api_key", "key", "token", "value", "secret"):
                v = row.get(f)
                if isinstance(v, str) and v == key:
                    return True
            return False

        usable = []
        for fn, row in candidates:
            if not _is_active(row):
                continue
            if _match(row, api_key_value):
                usable.append((fn, row))

        # Pick the most informative row (prefer one with scopes/quotas if present)
        def _score(item):
            _, r = item
            s = 0
            if isinstance(r.get("scopes"), list): s += 3
            if isinstance(r.get("scope"), str): s += 2
            if any(k in r for k in ("quota", "rate_limit", "limits", "plan")): s += 2
            if any(k in r for k in ("account_id", "workspace_id", "user_id", "owner_id")): s += 1
            return s

        if not usable:
            return None, None
        usable.sort(key=_score, reverse=True)
        return usable[0]

    try:
        rl = _rate_limit_check()
        if rl:
            _append_usage("RATE_LIMIT", (time.time() - t0) * 1000, apiKey_provided=bool(apiKey))
            return rl

        # Validate apiKey if provided
        if apiKey is not None and (not isinstance(apiKey, str) or not apiKey.strip()):
            _append_usage("VALIDATION_ERROR", (time.time() - t0) * 1000, apiKey_provided=True)
            return _err("VALIDATION_ERROR", "apiKey must be a non-empty string", field="apiKey")

        fn, cred = _find_best_credential(apiKey)
        if cred is None:
            _append_usage("UNAUTHORIZED", (time.time() - t0) * 1000, apiKey_provided=bool(apiKey))
            return _err("UNAUTHORIZED", "Missing or invalid credentials", field="apiKey" if apiKey is not None else "credentials")

        # Build identity response from whatever fields exist (do not fabricate)
        identity = {
            "credential_store": fn,
            "credential_id": cred.get("id"),
        }

        # attach known identity fields if present
        for k in ("account_id", "workspace_id", "user_id", "owner_id", "name", "email"):
            if k in cred:
                identity[k] = cred.get(k)

        scopes = None
        if isinstance(cred.get("scopes"), list):
            scopes = cred.get("scopes")
        elif isinstance(cred.get("scope"), str):
            scopes = [s for s in cred.get("scope").split() if s]
        identity["scopes"] = scopes or []

        # Provide basic observed rate usage for this endpoint (last minute)
        logs = _load("usage_logs.json")
        last_min = 0
        if isinstance(logs, list):
            cutoff = time.time() - 60.0
            for r in logs:
                if not isinstance(r, dict):
                    continue
                if r.get("endpoint") != "whoami-get" and r.get("tool_name") != "whoami-get":
                    continue
                ts = r.get("ts_epoch")
                if isinstance(ts, (int, float)) and ts >= cutoff:
                    last_min += 1

        resp = {
            "data": {
                "identity": identity,
                "rate_limit": {
                    "window_seconds": 60,
                    "max_requests": 120,
                    "used_requests": last_min,
                    "remaining_requests": max(0, 120 - last_min),
                },
            }
        }

        _append_usage("OK", (time.time() - t0) * 1000, apiKey_provided=bool(apiKey), credential_id=cred.get("id"), credential_store=fn)
        return resp
    except (ValueError, TypeError) as e:
        _append_usage("FAILED", (time.time() - t0) * 1000, apiKey_provided=bool(apiKey), error=str(e))
        return _err("VALIDATION_ERROR", "Invalid input", detail=str(e))
